        or (self.sourceConfig and Read(self.data,'GetConfig')~=self.sourceConfig)
        or (self.sourceBindings and Read(self.data,'GetBindings')~=self.sourceBindings)
        or (self.sourceRoads and Read(self.data,'GetRoadData')~=self.sourceRoads)
        or not TerrainCurrent(self) then reason='data_source_changed' end
