local function CaptureOrigin(self)
    local c=self.capture
    local position=namespace.NavigationV2Position
    local world=namespace.NavigationV2World
    local origin=c.requests.origin
    local point=type(origin)=='table' and origin.position
    local x,y
    if type(point)=='table' then
        if self.profile=='forever' then x,y=point.x,point.y else x,y=point.wx,point.wy end
    end
    if self.startMode~='player' or c.ready~=true or type(point)~='table'
        or not Finite(x) or not Finite(y)
        or type(position)~='table' or type(position.Observe)~='function'
        or type(world)~='table' or type(world.Match)~='function' then return {reliable=false} end
    self.stats.originCaptureCalls=self.stats.originCaptureCalls+1
    local ok,observed=APRPCall(position.Observe,c.api,1,false)
    if not ok or type(observed)~='table' then return {reliable=false} end
    local expected={world=point.world,floor=point.floor,phase=point.phase}
    if self.profile=='forever' or self.context.worldInput then
        expected.space=self.profile=='forever' and point.space or point.spaceID
        if point.z~=nil and (not Finite(point.z) or not Finite(observed.z)
            or math.abs(observed.z-point.z)>.01) then return {reliable=false} end
    end
    if world.Match(observed,expected)~=true or not Finite(observed.x) or not Finite(observed.y)
        or math.abs(observed.x-x)>.01 or math.abs(observed.y-y)>.01 then return {reliable=false} end
