end--[[APR_DIAG]]; CaptureOrigin = APRTrace("APR-Core/features/navigation/NavigationBenchmarkPreparation.lua:200:CaptureOrigin#22", CaptureOrigin)--[[/APR_DIAG]]

local function ClockAction(fact,nativeAt,solverAt)
