end--[[APR_DIAG]]; ClockAction = APRTrace("APR-Core/features/navigation/NavigationBenchmarkPreparation.lua:228:ClockAction#23", ClockAction)--[[/APR_DIAG]]

local function CaptureAction(self,key,request)
    local c=self.capture
    if type(request)~='table' then return nil,'invalid_observation_action' end
    local kind=request.kind
    local id=kind=='spell' and request.spellID or kind=='item' and request.itemID
    if not Finite(id) or id<1 or id%1~=0 or key~=kind..':'..id or request.id~=key then
        return nil,'invalid_observation_action'
    end
    local adapter=namespace.NavigationV2PersonalAdapter
    if type(adapter)~='table' or type(adapter.Observe)~='function' then return true end
    local declaration={id=key,kind=kind,spellID=request.spellID,itemID=request.itemID,chargeBased=request.chargeBased}
    if request.reagentID~=nil then declaration.reagents={{itemID=request.reagentID}} end
    self.stats.captureCalls=self.stats.captureCalls+1
    self.stats.personalCaptureCalls=self.stats.personalCaptureCalls+1
    local ok,observed=APRPCall(adapter.Observe,c.api,{declaration},nil,c.origin,false)
    if self.result then return true end
    if not ok or type(observed)~='table' then return true end
    local fact=type(observed.actions)=='table' and observed.actions[key]
    if type(fact)~='table' then return true end
    if kind=='item' and fact.castSeconds==nil and type(self.environment.getActionCastSeconds)=='function' then
        self.stats.environmentCaptureCalls=self.stats.environmentCaptureCalls+1
        local valid,value=APRPCall(self.environment.getActionCastSeconds,'item',id)
        if valid and Finite(value) and value>=0 then fact.castSeconds=value end
    end
    ClockAction(fact,observed.observedAt,c.solverAt)
    if not c.snapshot.personalObservation then
        c.snapshot.personalObservation=observed
        observed.observedAt=Finite(observed.observedAt) and c.solverAt or nil
        observed.revision=1
        observed.origin=c.origin.reliable and observed.origin or {reliable=false}
    end
    local target=c.snapshot.personalObservation
    target.actions[key]=fact
    for item,count in pairs(observed.items or {})do target.items[item]=count end
    self.stats.capturedActions=self.stats.capturedActions+1
    if type(self.context.actionPolicies)=='table' and self.context.actionPolicies[key]~=nil then
        c.snapshot.actionPolicies=c.snapshot.actionPolicies or {}
        c.snapshot.actionPolicies[key]=self.context.actionPolicies[key]
    end
    return true
end--[[APR_DIAG]]; CaptureAction = APRTrace("APR-Core/features/navigation/NavigationBenchmarkPreparation.lua:239:CaptureAction#24", CaptureAction)--[[/APR_DIAG]]

