local function CaptureBind(self)
    local c=self.capture
    if not c.bind then
        local name=BindName(self)
        if not name or type(self.bindings)~='table' then return true end
        c.bind={name=name,count=0}
    end
    local scan=c.bind
    local id,row=next(self.bindings,scan.cursor)
    scan.cursor=id
    if id==nil then
        if scan.match and not scan.incomplete and not scan.ambiguous then
            c.snapshot.dynamicPositions.bind={reliable=true,areaID=scan.match,
                inference='unique_exact_native_name_to_declared_area',observedName=scan.name}
            self.stats.capturedDynamic=self.stats.capturedDynamic+1
        end
        return true
    end
    scan.count=scan.count+1
    if scan.count>4096 then scan.incomplete=true;return true end
    if not Finite(id) or id<1 or id%1~=0 or type(row)~='table'
        or (row.areaID~=nil and row.areaID~=id) then scan.incomplete=true;return false end
    local reader=self.environment.getAreaName
    if type(reader)~='function' then scan.incomplete=true;return true end
    self.stats.environmentCaptureCalls=self.stats.environmentCaptureCalls+1
    local ok,name=APRPCall(reader,id)
    name=ok and PublicText(c.api,name)
    if not name then scan.incomplete=true
    elseif name==scan.name then
        if scan.match then scan.ambiguous=true else scan.match=id end
    end
    return false
