        or type(self.child.ResumeObservations)~='function' then return nil,'observation_capture_unavailable' end
    local requests,reason=self.child:GetObservationRequests()
    if type(requests)~='table' then return nil,reason or 'invalid_observation_requests' end
    for _,field in ipairs({'actions','quests','access','dynamic'})do
        if requests[field]~=nil and type(requests[field])~='table' then return nil,'invalid_observation_requests' end
    end
