    self.capture={requests=requests,snapshot=snapshot,stage=1,counts={},solverAt=self.context.clock()/1000}
    self.capture.api=ObservationAPI(self,self.context.api or {})
    self.capture.empty=true
    for _,field in ipairs({'actions','quests','access','dynamic'})do
        if next(requests[field] or {}) then self.capture.empty=false end
    end
    if not self.capture.empty then self.capture.ready=CaptureReady(self) end
    if self.result then return true end
    self.capture.origin=CaptureOrigin(self)
