            elseif c.ready~=true then
                c.snapshot.personalObservation={loading=c.ready==false and true or nil,origin={reliable=false},actions={},items={}}
                c.snapshot.conditionObservation={sequence=1,worldState='unknown',quests={},access={}}
                c.snapshot.dynamicPositions={}
            elseif c.snapshot.personalObservation then
                local origin=CaptureOrigin(self)
                if not origin.reliable then c.snapshot.personalObservation.origin={reliable=false} end
            end
            if c.bind and c.snapshot.dynamicPositions.bind then
                if BindName(self)~=c.bind.name or Read(self.data,'GetBindings')~=self.bindings then
                    c.snapshot.dynamicPositions.bind=nil
                end
