function Job:Step(operations,milliseconds)
    if self.result or ProfileChanged(self) then return self.result end
    if (operations~=nil and (not Finite(operations) or operations<1 or operations>4096 or operations%1~=0))
        or (milliseconds~=nil and (not Finite(milliseconds) or milliseconds<=0)) then
        CancelChild(self);self.capture=nil;self.loading=nil
        self.result={status='invalid',reason='invalid_step_budget'};return self.result
    end
    local result,reason
    if self.loading then result=LoadForever(self)
    elseif self.capture then result=CaptureStep(self,operations,milliseconds)
    else
        self.stats.producerStepCalls=self.stats.producerStepCalls+1
        result,reason=self.child:Step(operations,milliseconds)
        if type(result)=='table' and result.status=='running' and result.phase=='observation_required' then
            local ok,why=BeginCapture(self)
            if not ok then
                CancelChild(self);self.capture=nil
                result={status='unknown',reason=why}
            end
        end
    end
    if self.result then return self.result end
    if ProfileChanged(self) then return self.result end
    if type(result)=='table' and self.dataLoadCalls~=nil then
        result.diagnostics=result.diagnostics or {}
        result.diagnostics.dataLoadCalls=self.dataLoadCalls
    end
    if type(result)=='table' then
        result.diagnostics=result.diagnostics or {}
        for key,value in pairs(self.stats)do result.diagnostics[key]=value end
    end
    if type(result)=='table' and result.status~='running' then
        if self.terrainGaps and #self.terrainGaps>0 then
            result.provenance=result.provenance or {}
            result.provenance.terrainLoadReason=self.terrainGaps[1].reason
            result.provenance.terrainLoadScope=self.terrainGaps[1].id
            result.provenance.terrainLoadFailures=#self.terrainGaps
        end
        self.result=result;self.child=nil
    end
    return result,reason
end--[[APR_DIAG]]; Job.Step = APRTrace("APR-Core/features/navigation/NavigationBenchmarkPreparation.lua:749:Job:Step#46", Job.Step)--[[/APR_DIAG]]

local function NewJob(context)
