        or (point.z~=nil and not Finite(point.z)) then return end
    local result={x=point.x,y=point.y,z=point.z,uiMapID=point.uiMapID}
    if retail then result.space='world';result.instanceID=world;result.spaceID=point.spaceID
    else result.world=world;result.space=point.spaceID end
    for _,key in ipairs({'floor','phase','accessKey','region','noAutoconnect','terrainBoundary',
        'positionSource','heightSource','indoors'})do result[key]=point[key] end
