function namespace.NavigationV2PrepareWorld(request,context)
    if type(context)~='table' or type(context.clock)~='function' then return nil,'benchmark_v2_context_missing' end
    if type(request)~='table' then return nil,'benchmark_v2_request_invalid' end
    local profile=context.profile
    if profile~='retail' and profile~='forever' then return nil,'benchmark_v2_client_unknown' end
    local module=profile=='retail' and namespace.NavigationV2RetailData or namespace.NavigationV2ForeverData
    if type(module)~='table' or type(module.Prepare)~='function' then return nil,'benchmark_v2_preparation_unavailable' end
    local from,to=NativePoint(request.from,profile=='retail'),NativePoint(request.to,profile=='retail')
    if not from or not to then return nil,'benchmark_v2_request_invalid' end
    local source,reason=CaptureData(context.data,profile)
    if not source then return nil,reason end
    local captured={}
    for key,value in pairs(context)do captured[key]=value end
    captured.worldInput=true;captured.startMode=request.startMode;captured.dataLoadCalls=0
    captured.actor=context.actor or Character(context.environment)
    local job
    if profile=='forever' then
